    private TreeNode<T> rotateRight(TreeNode<T> node) {
        // If the node has a right child, it means it's a 1-2 tree case
        if (node.right != null) {
            // Get the right child's leftmost child
            TreeNode<T> rightChild = node.right;
            while (rightChild.left != null) {
                rightChild = rightChild.left;
            }

            // Right child becomes the parent of the original node
            node.right = rightChild.right;
            rightChild.right = node;

            // Update the parent of the right child's right child
            if (rightChild.right != null) {
                rightChild.right.parent = node;
            }

            // Update the parents of the original node and its right child
            node.parent = rightChild;
            rightChild.parent = node.parent;

            // If the original node's parent is not null, update its child pointers:
            // If the original node was the left child of its parent, make the right child of the original node the new left child of its parent
            // If the original node was the right child of its parent, make the right child of the original node the new right child of its parent
            if (node.parent != null) {
                if (node.parent.left == node) {
                    node.parent.left = rightChild;
                } else {
                    node.parent.right = rightChild;
                }
            }
        } else {
            // The node has no right child, so it doesn't need to be rotated
            return node;
        }
        return node.parent;
