public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
	checkArgument(genericType != null, "genericType cannot be null");
	checkArgument(targetType != null, "targetType cannot be null");

	// Check if the generic type is parameterized
	if (!(genericType instanceof ParameterizedType)) {
		return null;
	}

	// Get the type arguments of the generic type
	Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

	// Create an array to store the resolved arguments
	Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

	// Loop through the type arguments
	for (int i = 0; i < typeArguments.length; i++) {
		// Get the type argument
		Type typeArgument = typeArguments[i];

		// If the type argument is a type variable, resolve it using the target type
		if (typeArgument instanceof TypeVariable<?>) {
			resolvedArguments[i] = resolveTypeVariable(typeArgument, targetType);
		}
		// If the type argument is a class, return it directly
		else if (typeArgument instanceof Class<?>) {
			resolvedArguments[i] = (Class<?>) typeArgument;
		}
		// If the type argument is a wildcard, resolve it using the target type
		else if (typeArgument instanceof WildcardType) {
			resolvedArguments[i] = resolveWildcardType(typeArgument, targetType);
		}
	}

	return resolvedArguments;
}

/**
* Resolves a type variable using the target type.
* @param typeVariable The type variable to resolve
* @param targetType The target type to use for resolution
* @return The resolved type
*/
private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
	// Get the type variable bounds
	Type[] typeVariableBounds = typeVariable.getBounds();

	// Check if the type variable is bounded
	if (typeVariableBounds.length > 0) {
		// Get the first bound
		Type typeVariableBound = typeVariableBounds[0];

		// If the bound is a class, return it directly
		if (typeVariableBound instanceof Class<?>) {
			return (Class<?>) typeVariableBound;
		}
		// If the bound is a wildcard, resolve it using the target type
		else if (typeVariableBound instanceof WildcardType) {
			return resolveWildcardType(typeVariableBound, targetType);
		}
	}

	// If the type variable is unbounded, return Object.class
	return Object.class;
}

/**
* Resolves a wildcard type using the target type.
* @param wildcardType The wildcard type to resolve
* @param targetType The target type to use for resolution
* @return The resolved type
*/
private static Class<?> resolveWildcardType(WildcardType wildcardType, Class<?> targetType) {
	// Get the upper bounds
	Type[] upperBounds = wildcardType.getUpperBounds();

	// Check if the wildcard type has upper bounds
	if (upperBounds.length > 0) {
		// Get the first upper bound
		Type upperBound = upperBounds[0];

		// If the upper bound is a class, return it directly
		if (upperBound instanceof Class<?>) {
			return (Class<?>) upperBound;
		}
		// If the upper bound is a wildcard, resolve it using the target type
		else if (upperBound instanceof WildcardType) {
			return resolveWildcardType(upperBound, targetType);
		}
	}

	// If the wildcard type has no upper bound, return the target type
	return targetType;
}

