/**
* @param descriptor a type or method descriptor (in which case its argument types are popped).
*/
private void pop(final String descriptor) {
    // Check if the descriptor is a valid type descriptor
    if (!descriptor.startsWith("(") || !descriptor.endsWith(")")) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Get the number of argument types in the descriptor
    int numArguments = descriptor.length() - 2;

    // Create an array to store the popped argument types
    Class<?>[] poppedArguments = new Class<?>[numArguments];

    // Pop each argument type from the output frame stack
    for (int i = numArguments - 1; i >= 0; i--) {
        String argumentType = descriptor.substring(i + 1, i + 2);
        poppedArguments[i] = popArgumentType(argumentType);
    }

    // Return the popped argument types as an array
    return poppedArguments;
}

/**
* @param descriptor a type descriptor.
* @return the corresponding {@link Class} object.
*/
private Class<?> popArgumentType(final String descriptor) {
    switch (descriptor) {
        case "Z": // boolean
            return boolean.class;
        case "B": // byte
            return byte.class;
        case "C": // char
            return char.class;
        case "S": // short
            return short.class;
        case "I": // int
            return int.class;
        case "F": // float
            return float.class;
        case "J": // long
            return long.class;
        case "D": // double
            return double.class;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

