    // iterate over the edges in the tour set
    for (E edge : tour) {
        // get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // add a new edge and vertex to the graph path
        path.addEdge(graph.findVertex(source), graph.findVertex(target));
    }

    return path;
