public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices are all vertices in the graph
    if (!graph.getVertices().containsAll(vertices)) {
        throw new IllegalArgumentException("The given vertices are not all vertices in the graph");
    }

    // Check if the given vertices can form a complete subgraph
    if (vertices.size() < 2) {
        return false;
    }

    // Check if all possible pairs of vertices in the given set are adjacent
    for (int i = 0; i < vertices.size(); i++) {
        for (int j = i + 1; j < vertices.size(); j++) {
            V vertex1 = vertices.get(i);
            V vertex2 = vertices.get(j);
            if (!graph.isAdjacent(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

